import { sum } from './sum.mjs';
if (sum(2, 2) !== 4) { console.error('FAIL'); process.exit(1); }
console.log('ok');

export function calc(items) {
  return items.reduce((s, x) => s + x, 0);
}

import { calc } from './lib.mjs';
const t = calc([1, 2, 3]);
if (t !== 6) process.exit(1);
console.log('ok', t);

export function range(start, end) {
  const out = [];
  for (let i = start; i < end; i++) out.push(i);
  return out;
}

import { range } from './range.mjs';
const r = range(1, 3).join(',');
if (r !== '1,2,3') { console.error('got', r); process.exit(1); }
console.log('ok');
